import math, random
from nearproof import (
    ConsensusPolicy, Observation, RangeDecision, assess_polygon_geofence,
)

rng = random.Random(7)

def rand_convex_polygon():
    n = rng.randint(3, 8)
    angles = sorted(rng.uniform(0, 2 * math.pi) for _ in range(n))
    pts = []
    for a in angles:
        r = rng.uniform(1.0, 6.0)
        pts.append((r * math.cos(a), r * math.sin(a)))
    # verify strict convexity in float; retry recursively if degenerate
    m = len(pts)
    sign = 0
    for i in range(m):
        ax, ay = pts[i]; bx, by = pts[(i+1) % m]; cx, cy = pts[(i+2) % m]
        cross = (bx-ax)*(cy-by) - (by-ay)*(cx-bx)
        if cross == 0 or (sign and (cross > 0) != (sign > 0)):
            return rand_convex_polygon()
        sign = 1 if cross > 0 else -1
    return tuple(pts)

def rand_case():
    n = rng.randint(1, 4)
    obs = tuple(
        Observation(id=f"o{i}", x=rng.uniform(-4, 4), y=rng.uniform(-4, 4),
                    decision=RangeDecision(1, rng.uniform(0.2, 4), True))
        for i in range(n)
    )
    weights = {o.id: rng.randint(1, 3) for o in obs}
    policy = ConsensusPolicy(weights, rng.randint(1, sum(weights.values())))
    tol = rng.choice([0.0, rng.uniform(0, 0.5)])
    return obs, policy, rand_convex_polygon(), tol

bad = 0
for trial in range(3000):
    obs, policy, poly, tol = rand_case()
    base = assess_polygon_geofence(obs, policy, poly, tolerance=tol)
    k = rng.randrange(len(poly))
    rotated = poly[k:] + poly[:k]
    reversed_poly = tuple(reversed(poly))
    r1 = assess_polygon_geofence(obs, policy, rotated, tolerance=tol)
    r2 = assess_polygon_geofence(obs, policy, reversed_poly, tolerance=tol)
    r3 = assess_polygon_geofence(tuple(reversed(obs)), policy, poly, tolerance=tol)
    if not (base == r1 == r2 == r3):
        bad += 1
        print("INVARIANCE FAIL", base, r1, r2, r3, obs, policy, poly, tol)
        if bad > 3:
            break
print("invariance failures:", bad)

# Sampling smoke test: independent float classification on a dense grid.
def classify_by_sampling(obs, policy, poly, tol):
    weights = policy.weights
    def feasible(px, py):
        w = 0
        for o in obs:
            if math.hypot(px - o.x, py - o.y) <= o.decision.upper_bound + tol:
                w += weights[o.id]
        return w >= policy.threshold
    def inside(px, py):
        m = len(poly)
        sign = 0
        for i in range(m):
            ax, ay = poly[i]; bx, by = poly[(i+1) % m]
            cross = (bx-ax)*(py-ay) - (by-ay)*(px-ax)
            if cross == 0:
                continue
            s = 1 if cross > 0 else -1
            if sign == 0:
                sign = s
            elif s != sign:
                return False
        return True
    xs = [p[0] for p in poly]; ys = [p[1] for p in poly]
    lo_x, hi_x = min(xs)-8, max(xs)+8
    lo_y, hi_y = min(ys)-8, max(ys)+8
    has_in = has_out = False
    N = 300
    for i in range(N+1):
        for j in range(N+1):
            px = lo_x + (hi_x-lo_x)*i/N
            py = lo_y + (hi_y-lo_y)*j/N
            if feasible(px, py):
                if inside(px, py):
                    has_in = True
                else:
                    has_out = True
    if has_in:
        return "mixed" if has_out else "inside"
    return "outside" if has_out else "empty"

mismatch = 0
for trial in range(400):
    obs, policy, poly, tol = rand_case()
    exact = assess_polygon_geofence(obs, policy, poly, tolerance=tol)
    sampled = classify_by_sampling(obs, policy, poly, tol)
    # sampling can miss thin slivers; only count contradictions where the
    # sampler found evidence the exact result denies
    contradiction = (
        (sampled == "mixed" and exact in ("inside", "outside"))
        or (sampled == "inside" and exact in ("empty", "outside"))
        or (sampled == "outside" and exact in ("empty", "inside"))
        or (sampled in ("inside", "outside", "mixed") and exact == "empty")
    )
    if contradiction:
        mismatch += 1
        print("SAMPLE CONTRADICTION exact=", exact, "sampled=", sampled, obs, policy, poly, tol)
        if mismatch > 3:
            break
print("sampling contradictions:", mismatch)
